import{_ as t,o as a,c as i,ai as r}from"./chunks/framework.DQi1ytmF.js";const u=JSON.parse('{"title":"Where to go next","description":"","frontmatter":{},"headers":[],"relativePath":"learn/next.md","filePath":"learn/next.md"}'),n={name:"learn/next.md"};function o(s,e,h,l,d,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h1><p>You have the whole mental model: <strong>declare with a name, yield what you do not own, derive the rest.</strong> Everything below is a variation on it.</p><h2 id="fill-the-gaps-in-what-you-built" tabindex="-1">Fill the gaps in what you built <a class="header-anchor" href="#fill-the-gaps-in-what-you-built" aria-label="Permalink to &quot;Fill the gaps in what you built&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You have</th><th>Next thing worth adding</th></tr></thead><tbody><tr><td>A query and a mutation</td><td><a href="/craft/guide/state/persistence.html">Persistence</a> — storage persistence as an insertion (localStorage by default)</td></tr><tr><td>A list</td><td><a href="/craft/guide/state/collections.html">Collections</a> — entity storage, selectors, updates</td></tr><tr><td>A form</td><td><a href="/craft/guide/forms/validation.html">Validation</a> — custom and async validators</td></tr><tr><td>Routes</td><td><a href="/craft/guide/routing/guards.html">Route guards</a> and <a href="/craft/guide/routing/route-providers.html">Route providers</a></td></tr><tr><td>A running app</td><td><a href="/craft/guide/routing/pending-ui.html">Non-blocking navigation</a> — pending UI instead of a freeze</td></tr></tbody></table><h2 id="concepts-worth-a-dedicated-read" tabindex="-1">Concepts worth a dedicated read <a class="header-anchor" href="#concepts-worth-a-dedicated-read" aria-label="Permalink to &quot;Concepts worth a dedicated read&quot;">​</a></h2><ul><li><a href="/craft/guide/concepts/mental-model.html">The mental model</a> — the design principles behind the API you just used</li><li><a href="/craft/guide/concepts/exceptions.html">Exceptions as values</a> — declared failures, exhaustively handled</li><li><a href="/craft/guide/concepts/insertions.html">Insertions</a> — writing your own and composing them</li><li><a href="/craft/guide/concepts/insertion-pipes.html">Typed insertion pipes</a> — readable composition for each primitive</li><li><a href="/craft/guide/concepts/generators.html">Generators</a> — <code>craftGen</code> outside a service</li></ul><h2 id="teach-the-app-its-boundaries" tabindex="-1">Teach the app its boundaries <a class="header-anchor" href="#teach-the-app-its-boundaries" aria-label="Permalink to &quot;Teach the app its boundaries&quot;">​</a></h2><p>The graph you just tested is also a map you can constrain. <a href="/craft/guide/testing/architecture.html">Architecture rules</a> are ordinary Vitest assertions on the static Craft graph: unique identities, unique HTTP, pure <code>craftComputed</code>, folder lanes, exclusive feature branches — and any neighbourhood you can look up is a rule you can write. Nx still owns the workspace graph (imports, affected, cache); Craft judges the app. <a href="/craft/guide/testing/craft-graph-vs-nx.html">Craft graph vs Nx</a> is the split.</p><p>Setup is in that guide. The demo suite already runs them:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> architecture</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span></span></code></pre></div><h2 id="when-your-app-grows" tabindex="-1">When your app grows <a class="header-anchor" href="#when-your-app-grows" aria-label="Permalink to &quot;When your app grows&quot;">​</a></h2><ul><li><a href="/craft/guide/app/service-scopes.html">Service scopes</a> — when <code>function</code> stops being enough</li><li><a href="/craft/guide/routing/scaling.html">Scaling routes</a> — splitting collections before TypeScript&#39;s instantiation ceiling bites</li><li><a href="/craft/guide/app/lazy-services.html">Lazy services</a> and <a href="/craft/guide/app/app-start.html">App start</a></li><li><a href="/craft/guide/advanced/observability.html">Observability</a> — logging and tracing that follow the dependency graph</li></ul><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><p>Looking for one symbol? The <a href="/craft/reference/">API index</a> lists every export with a one-line description and a link.</p><h2 id="see-it-running" tabindex="-1">See it running <a class="header-anchor" href="#see-it-running" aria-label="Permalink to &quot;See it running&quot;">​</a></h2><p><a href="/craft/resources/examples.html">Examples</a> points at the demo application, which exercises most of the above end to end.</p><div style="margin-top:2rem;"><p><a href="/craft/learn/10-testing.html">← 10. Test what you wrote</a></p></div>',17)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
